(889, 1, 'TECHNIP', 'CDA - TFMC', 'Aeroporto de Cabo Frio', '{"grupo":"TECHNIP","unidade":"CDA - TFMC","data":"2026-08-10","local":"Aeroporto de Cabo Frio","modal":"Helicóptero","preposto":"Ítalo Gabriel","observacao_nome_arquivo":"","horarios":{"saida_hotel":[{"label1":"Previsto","h1":"05","m1":"00","label2":"Real","h2":"04","m2":"58"}],"embarque_previsto":"06:40","embarque_real":"09:52","atendimento_inicio":"04:03","atendimento_fim":"12:40"},"info_troca":"Devido às condições meteorológicas adversas nos aeroportos de Cabo Frio, Maricá e Jacarepaguá, os voos permaneceram temporariamente suspensos no aguardo de melhoria climática.<div><br><div>Após a liberação do espaço aéreo, o portão de embarque foi solicitado às 09:52h e a decolagem ocorreu às&nbsp;<span style=\"font-size: 1rem; -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">10:19h.<\/span><\/div><\/div><div><span style=\"font-size: 1rem; -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\"><br><\/span><\/div><div><span style=\"font-size: 1rem; -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;\">O colaborador Fabio da Costa Carneiro optou por seguir por meios próprios.<\/span><\/div>","pax_embarcando":"*TFMC*\n1.ELOA LEMOS DOS SANTOS MORGADO\n2.PAULO RIBEIRO AGLIARDI\n\n*UTEC*\n3.DOUGLAS DA SILVA SILVEIRA\n\n*UNIFLEX*\n4.PABLO ROBERTO PEIXOTO DA SILVA SOUZA\n5.LUIZ VINICIUS DA SILVA\n6.ROMULO FRANCISCO DE SOUZA\n7.NILTON CESAR MENDES DA SILVA JUNIOR\n8.PEDRO LUCAS VIEIRA MANGARAVITE\n9.ORLANDO SOARES NETO","pax_desembarcando":"*TFMC*\n1.FABIO DA COSTA CARNEIRO\n\n*UTEC*\n2.LEANDRO PICKHARDT\n\n*UNIFLEX*\n3.LEONARDO SOARES BARBOSA\n4.MARCOS VINICIUS NASCIMENTO CARVALHO\n5.LUIZ FELIPE PINTO DIAS DA SILVA\n6.LEANDRO DA SILVA CARVALHO\n7.ISAIAS GOMES ALVES","fotos":[]}', 0, NULL, '2026-08-10 15:58:23', '2026-08-10 15:58:24', 'TECHNIP', NULL, 'relatorios_pdf/6a79f520e9f73_CDA_-_TFMC_10-08-2026_(06:40h).pdf', '187.63.9.234'),
